+}
+
+// ── Comments ─────────────────────────────────────────────────────────────
+
+function buildTransplantComment(fields) {
+    var f = fields || {};
+    var carried = (f.carriedLabels && f.carriedLabels.length)
+        ? 'Carried review verdicts: ' + f.carriedLabels.join(', ') + '.'
