+    for (var i = 0; i < MARKER_KEYS.length; i++) {
+        var k = MARKER_KEYS[i];
+        if (f[k] === undefined || f[k] === null || f[k] === '') continue;
+        pairs.push(k + '="' + String(f[k]).replace(/["\\\r\n]/g, ' ') + '"');
+    }
+    return '<!-- guest-transplant ' + pairs.join(' ') + ' -->\n' + markerHumanLine(f);
+}
