+function diffFingerprint(diffText) {
+    if (typeof diffText !== 'string' || !diffText.length) return null;
+    var t = diffText.replace(/\r\n/g, '\n');
+    t = t.replace(/\n+$/, '\n');
+    if (t.charAt(t.length - 1) !== '\n') t += '\n';
+    return t;
