+    var fp2 = diffFingerprint(transplantDiff);
+    if (fp1 === null) return { carry: false, labels: [], reason: 'source-diff-unavailable' };
+    if (fp2 === null) return { carry: false, labels: [], reason: 'transplant-diff-unavailable' };
+    if (fp1 === fp2) {
