    // defaults when absent.
    var priorityLabels = resolvePriorityLabels(ctx && ctx.priorityLabels);
    if (q.type === 'pr') {
        return queryPrs(rule, provider, repoInfo, limit, machineAuthor, owner, priorityLabels);
