+function transplantBodySteps(ctx, sha) {
+    var cfg = ctx.cfg;
+    var branch = transplantBranchName(cfg.branchPrefix, ctx.source.prNumber);
+    var title = guestPrTitle(cfg, ctx.source.prNumber, ctx.source.title);
