+            decision: 'complete-orphan',
+            reason: 'orphan-branch-completed',
+            steps: transplantBodySteps({ cfg: cfg, base: base, source: source }, shaInfo.sha),
+            audit: audit + 'completing orphan transplant from branch ' + branch
+        };
+    }
