              head: { sha: 'a3', ref: 'gone', repo: null },
              labels: [{ name: 'po_accept' }], user: { login: 'extc' } }
        ];
    }

    function gtQuery(prs, query) {
        return gtLoad({
            github_list_prs: function () { return prs; }
        }).query({ query: query, limit: 5 },
