        assert.equal(mod.buildDeleteRefCommand('acme', 'widget', 'ai/guest-42'),
            'gh api repos/acme/widget/git/refs/heads/ai/guest-42 -X DELETE');
        assert.equal(mod.buildMainHeadCommand('acme', 'widget', 'main'),
