            { query: { type: 'pr', notMergeState: ['DIRTY'] } }, null, null, 'o', repoInfo), false,
            'mergeState on the not-list fails');
    });

    test('a matching PR state survives the chain; crossRepo false-paths a same-repo head in-chain', function () {
        var gt = mgLoad();
