        assert.equal(gt.matchesGuards(open,
            { query: { type: 'pr', crossRepo: true } }, null, null, 'o', repoInfo), false,
            'crossRepo: same-repo head fails inside matchesGuards');
        var fork = { prNumber: 503, labels: [], headRepo: 'extc/fork',
