631:function transplantSequence(input) {
632:    var cfg = input.cfg;
633:    var source = input.source || {};
634:    var labels = source.labels || [];
635:    var base = input.base || { owner: '', repo: '', baseBranch: cfg.baseBranch };
636:    var audit = 'guest-transplant: #' + String(source.prNumber) + ' ';
637:
638:    // AC5 — a source closed by hand before the tick is skipped.
639:    if (source.state && source.state !== 'OPEN') {
640:        return { decision: 'skip', reason: 'source-closed', steps: [],
641:                 audit: audit + 'skipped — source is ' + source.state };
642:    }
643:    // The configured label must actually be present.
644:    if (labels.indexOf(cfg.label) === -1) {
645:        return { decision: 'skip', reason: 'not-armed', steps: [],
646:                 audit: audit + 'skipped — no ' + cfg.label + ' label' };
647:    }
648:    // AC5 — only a HUMAN actor's label arms a transplant; missing proof
649:    // refuses (fail closed — the label is the voucher).
650:    var actor = classifyArmActor(input.armEvent, input.machineLogins);
651:    if (actor !== 'human') {
652:        return { decision: 'refuse', reason: actor === 'machine' ? 'machine-actor' : 'actor-unverified',
653:                 steps: [], audit: audit + 'REFUSED — arm actor is ' + actor + ' (audit only, no action)' };
654:    }
655:    // E3 — transplant is cross-repo only; a same-repo label is a no-op.
656:    if (!isCrossRepoHead(source.headRepo, base.owner, base.repo)) {
657:        return { decision: 'skip', reason: 'same-repo', steps: [],
658:                 audit: audit + 'skipped — same-repo head (transplant is cross-repo only)' };
659:    }
660:    // AC5 — snapshot semantics: one live transplant per source.
661:    if (input.openTransplantPr ||
662:        (input.marker && input.marker.state === 'transplanted')) {
663:        return { decision: 'noop', reason: 'already-transplanted', steps: [],
664:                 audit: audit + 'no-op — transplant already exists' };
665:    }
666:
667:    var parkedHere = labels.indexOf(cfg.parkedLabel) !== -1;
668:    var marker = input.marker || null;
669:
670:    // AC4 — the park is a pure function of the head (#633 semantics): a
671:    // parked source whose head CHANGED re-arms (label off, transplant
672:    // proceeds below); an unchanged head stays parked; a human 'blocked'
673:    // with NO park marker of ours is a human hold — never touched.
674:    if (parkedHere) {
675:        var isOurPark = marker && marker.state === 'parked';
676:        if (!isOurPark) {
677:            return { decision: 'skip', reason: 'human-blocked', steps: [],
678:                     audit: audit + 'skipped — ' + cfg.parkedLabel + ' without a transplant park marker (human hold)' };
679:        }
680:        var moved = input.headSha && marker.head && input.headSha !== marker.head;
681:        if (!moved) {
682:            return { decision: 'noop', reason: 'parked-head-unchanged', steps: [],
683:                     audit: audit + 'no-op — parked head unchanged' };
684:        }
685:        var unpark = [step('remove_label', { prNumber: source.prNumber, label: cfg.parkedLabel })];
686:        var rearmMarker = step('comment', {
687:            prNumber: source.prNumber,
688:            text: transplantMarkerComment({
689:                state: 'armed', source: source.prNumber,
690:                head: input.headSha,
691:                branch: transplantBranchName(cfg.branchPrefix, source.prNumber)
692:            })
693:        });
694:        return {
695:            decision: 'transplant',
696:            reason: 'park-reset',
697:            steps: unpark.concat([rearmMarker, step('create_ref', {
698:                branch: transplantBranchName(cfg.branchPrefix, source.prNumber),
699:                atBranch: cfg.baseBranch
700:            })]).concat(transplantBodySteps(
701:                { cfg: cfg, base: base, source: source }, input.headSha)),
702:            audit: audit + 'park reset — head moved ' + String(marker.head) + ' → ' +
703:                String(input.headSha) + ' (re-arming the transplant)'
704:        };
705:    }
706:
707:    // The transplant sha: the marker's recorded arm-time sha wins (E1).
708:    var shaInfo = resolveTransplantSha(marker, input.headSha);
709:    if (!shaInfo) {
710:        // AC4 fallback — no readable head: park with the no-ref reason.
711:        var steps = parkSteps('no-ref', { cfg: cfg, source: source, headSha: null });
712:        return { decision: 'park', reason: 'no-ref', steps: steps,
713:                 audit: audit + 'parked — no-ref (source head unreadable)' };
714:    }
715:
716:    var branch = transplantBranchName(cfg.branchPrefix, source.prNumber);
717:
718:    // E5 — an orphan branch from a dead tick completes from the marker
719:    // (merge re-issued: an already-merged API merge is a harmless
720:    // no-content answer) instead of crashing the key idempotency.
721:    if (input.branchExists && !input.openTransplantPr) {
722:        if (!marker) {
723:            return { decision: 'gc-orphan', reason: 'orphan-branch-no-marker',
724:                     steps: [step('delete_ref', { branch: branch })],
725:                     audit: audit + 'GC — orphan branch ' + branch + ' with no arm marker' };
726:        }
727:        return {
728:            decision: 'complete-orphan',
729:            reason: 'orphan-branch-completed',
730:            steps: transplantBodySteps({ cfg: cfg, base: base, source: source }, shaInfo.sha),
731:            audit: audit + 'completing orphan transplant from branch ' + branch
732:        };
733:    }
734:
735:    // Fresh transplant: record the arm marker (the snapshot for E1/E5),
736:    // cut the branch at main, merge the recorded sha, open the machine PR.
737:    var fresh = [];
738:    if (!marker) {
739:        fresh.push(step('comment', {
740:            prNumber: source.prNumber,
741:            text: transplantMarkerComment({
742:                state: 'armed', source: source.prNumber, head: shaInfo.sha, branch: branch
743:            })
744:        }));
745:    }
746:    fresh.push(step('create_ref', { branch: branch, atBranch: cfg.baseBranch }));
747:    return {
