+// The workflow graph keyed by job id (the wiring check's lookup shape).
+function _jobsByIdOf(jobs) {
+    var jobsById = {};
+    jobs.forEach(function (j) {
+        if (j && j.id) jobsById[String(j.id)] = { id: String(j.id), needs: (j.needs || []).map(String) };
