636:    var audit = 'guest-transplant: #' + String(source.prNumber) + ' ';
637:
638:    // AC5 — a source closed by hand before the tick is skipped.
639:    if (source.state && source.state !== 'OPEN') {
640:        return { decision: 'skip', reason: 'source-closed', steps: [],
641:                 audit: audit + 'skipped — source is ' + source.state };
642:    }
643:    // The configured label must actually be present.
644:    if (labels.indexOf(cfg.label) === -1) {
645:        return { decision: 'skip', reason: 'not-armed', steps: [],
646:                 audit: audit + 'skipped — no ' + cfg.label + ' label' };
647:    }
648:    // AC5 — only a HUMAN actor's label arms a transplant; missing proof
649:    // refuses (fail closed — the label is the voucher).
650:    var actor = classifyArmActor(input.armEvent, input.machineLogins);
651:    if (actor !== 'human') {
652:        return { decision: 'refuse', reason: actor === 'machine' ? 'machine-actor' : 'actor-unverified',
653:                 steps: [], audit: audit + 'REFUSED — arm actor is ' + actor + ' (audit only, no action)' };
654:    }
655:    // E3 — transplant is cross-repo only; a same-repo label is a no-op.
656:    if (!isCrossRepoHead(source.headRepo, base.owner, base.repo)) {
657:        return { decision: 'skip', reason: 'same-repo', steps: [],
658:                 audit: audit + 'skipped — same-repo head (transplant is cross-repo only)' };
659:    }
660:    // AC5 — snapshot semantics: one live transplant per source.
661:    if (input.openTransplantPr ||
662:        (input.marker && input.marker.state === 'transplanted')) {
663:        return { decision: 'noop', reason: 'already-transplanted', steps: [],
