        return { decision: 'skip', reason: 'source-closed', steps: [],
                 audit: audit + 'skipped — source is ' + source.state };
    }
    if (labels.indexOf(cfg.label) === -1) {
        return { decision: 'skip', reason: 'not-armed', steps: [],
