    if (!e || !e.branch) return null;
    if (e.prState === 'CLOSED' || e.prState === 'MERGED') {
        return step('delete_ref', { branch: e.branch });
    }
    if (e.prState === 'OPEN') return null;
    // No PR on this branch (yet/anymore).
